import{_ as t,o as l,c as n,j as e,a as r}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第101章 坐下来了","description":"","frontmatter":{},"headers":[],"relativePath":"第101章_坐下来了.md","filePath":"第101章_坐下来了.md"}'),o={name:"第101章_坐下来了.md"};function s(_,a,p,c,d,i){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"第101章-坐下来了",tabindex:"-1"},[r("第101章 坐下来了 "),e("a",{class:"header-anchor",href:"#第101章-坐下来了","aria-label":'Permalink to "第101章 坐下来了"'},"​")],-1),e("p",null,"我们第一次坐下来讲话，是毕业那年的七月。那一次不是我们约的。是账。她那年在国内接了一个团购的活，做二次分装。她那边走不通快递，她需要一个人在我们这边收货、拆包、按单发出去。她找我。她说，我要找一个人帮我发东西。我说，你找我。她说，我这边只有你。我说，为什么是我。她说，因为你不问。她说，我要是找何叶，她第一天就会问这人是谁。她说，我要是找我妹，她拿去玩了。她说，你什么都不问。我说，我今年问了一句。她说，你那句我记着呢，你后来也没讲。她说，你就当我没听到。我说，行。她说，那我开始讲了。她说，一箱大概五十件，我一个月发两箱。她说，你帮我拆开，按我的单子分装，装好，贴单，发出去。她说，一单我给你一块五。我说，不用。她说，你必须拿。我说，为什么。她说，因为你不拿你就又是白干。她说，你一白干你讲话就开始绕。她说，你绕起来我接不住。她说，你收了钱，我们就是办事，办事的人心里是平的。我说，那我收。她说，对。她说，我们周六见一面，我把单子当面给你讲一次，线上讲不清。我说，好。",-1),e("p",null,"周六是七月八号。她定的那个地方是一个奶茶店。她选那个店的原因，她后来跟我讲了。她说，那家店有六个位置靠窗。她说，靠窗那排坐得下两个人，而且背后没有人。她说，我背后有人我不敢讲话。她说，我选了三家店，最后选了这里。我说，你选店还查背后有没有人。她说，我这辈子做事都查这个。",-1),e("p",null,'两点我到了。她已经在。她坐在那一排最里面那个位子。我看见她的时候，我第一反应是很土的一句话。我想的是：她比照片老。我那时候不知道"老"这个字怎么来的。她那年二十四，我二十四。她头发扎着，脸上有一块很小的、在眼睛下面的斑。她手上戴着一只很旧的塑料表。她穿一件深色的短袖，肘那里有一道折痕。她抬头看我。她说，你来了。我说，我来了。她说，你坐。我坐下来。我把包放在桌上，我又拿下来，我放在脚边。那个动作我做了两次。她看着我笑了一下。她说，你这个人，你在椅子上坐不住。我说，我坐着。她说，你屁股往前三分之二。我说，什么。她说，你现在坐的是那种随时要走的位子。她说，你以前在电话亭外头等人就是这个坐法。她说，你放松一点，我今天只有一个钟头。我往后靠了。那个椅子背后是空的，靠下去那一下我反而紧张。',-1),e("p",null,"她先把一个袋子推到桌子中间。她说，这是单子。她说，我今天不讲怎么发，我今天讲三件事。我说，你说。她说，第一件，钱怎么走。她说，第二件，出错怎么办。她说，第三件，你别问我为什么找你。我说，第一件你说。她讲了二十分钟。她讲得非常清楚。清楚到我从包里拿出笔，在一张纸上记下来。我记的时候，她在那儿看着我。她说，你真的写。我说，我习惯。她说，你写这些，我明天就看不到了。我说，我给自己看。她说，你以后不要写。我说，为什么。她说，因为你写下来的东西，你就不会错。她说，你不会错，我这边出了错，就是我在错。她说，我们两个里必须有一个人会错。她说，我不太愿意那个人是我。我说，那我也不愿意是你。她说，那你别记。我说，好，我不记。我那天把笔放回包里。我一个字也没写。",-1),e("p",null,"那一个钟头里，第二件、第三件她讲完了。第三件她讲得最短。她说，你别问为什么找我。她说，因为我要是回答了你这个问题，我今天下午回去就要开始想我们是什么。她说，我今天下午还要去一个地方，我不能带着那个想。我说，那你今天这个决定是什么。她说，这个是收人。她说，我今天收了一个人。她说，这个决定很小，它不牵扯任何别的东西。她说，我们把它当成一件事定下来。",-1),e("p",null,'那天下午两点五十，她站起来。她说，我先走了。我说，我送。她说，不用，我打车。她说，你坐在这儿再十分钟。我说，为什么。她说，因为你要是跟我一起出去，我们在那门口要站一会儿。她说，那个门口站着会说话。她说，我们今天不要说那种话。我说，哪种话。她说，你知道哪种。她走了。我一个人坐在那张椅子上。桌上留着她那杯没喝完的东西。那一杯底下有一圈水痕，压得在木头上很白。我把那个杯子往我这边挪了一点，我又挪回去了。后来我发现一件事。桌上那个付款的单子不见了。我出去问那个店员。我说，刚刚坐这个位的人付了吗。他说，付了。我说，她一个人付两杯？他说，她付的时候讲了，她说这两杯都是公事。我那天下午在回去的路上想这句话想了很久。她说的是"这两杯都是公事"。她今天把两杯的钱一起付了，是因为她要这个下午从第一分钟到最后一分钟都是公事。她不能欠我一杯饮料。一杯三十一块的饮料，在她那里是一句可以拿来讲的东西。她今天把它斩了。而我那天下午坐在那张椅子上，连一杯三十一块都没有付成。',-1),e("p",null,"十点五十我出去。我在那个门口站了一下。我看见她过那条马路，她走得不快。她走到对面，没有回头。我那天下午在回去的公交上，想的是她在电话里说的那一句。她说，我这辈子做过的所有决定，都是在没有人的时候做的。她说，今天这个决定是在有人看着的情况下做的。她说，所以我今天做得很顺利。我那时候以为她说的是收我做事这件事很顺利。很多年以后我才反应过来，她那天讲的顺利，是说她终于有一件可以当着人做的正事。那件事里没有我。我只是那件正事里的一颗螺丝。而我那天下午很高兴。因为我第一次在她那里有一个不尴尬的位置。",-1)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
